    print(f"FAIL: {m}", file=sys.stderr)

def ok(m):
    print(f"OK: {m}", file=sys.stderr)

tests = Path(os.environ["TESTS_DIR"])
http_path = Path(os.environ["HTTP_RULES"])
tls_path = Path(os.environ["TLS_RULES"])
yaml_path = Path(os.environ["YAML"])
